/* 
	Hexa Life
	Game of Life on a hexagonal grid with gradient tiles 
	https://openprocessing.org/sketch/2140375
	#genuary10 #genuary #creativecoding #generativeart

	https://genuary.art/prompts#jan10
*/

const SZE = 75;
let board, tiles;
let NUMX, NUMY, clrs;

function setup() {
	// SZE = ~~random(100, 150);
	NUMX = ~~(windowWidth/Tile.getSpacingX(SZE)+1);
	NUMY = ~~(windowHeight/Tile.getSpacingY(SZE)+1);
	// createCanvas(SZE * NUMX, SZE * NUMY);
	createCanvas(windowWidth, windowHeight);
	describe("Game of Life on a hexagonal grid with gradient tiles")
	pixelDensity(1)
	frameRate(5)
	colorMode(HSB, 100);
	clrs = genColors(2, random(20, 50));
	board = new GoL(NUMX, NUMY, SZE);
	// initTiles();
}

function draw() {
	background("rgb(2, 0, 8)")
	board.update()
	board.show(clrs)
}

function mousePressed() {
	if (mouseButton === LEFT) setup();
}

function genColors(n = 2, space = 100) {
	arr = [];
	const HUE = ~~random(100)
	const DLT = space / n;
	for (let i = 0; i < n; i++) {
		let clr = color((HUE + i * DLT) % 100, random(75, 100), random(50, 75));
		arr.push(clr)
	}
	return arr;
}

class GoL {
	constructor(_dx, _dy, _sz) {
		this.dx = _dx;
		this.dy = _dy;
		this.sz = _sz;
		this.init();
	}

	init() {
		this.tiles = this.initArray(true);
		this.nbs = this.initArray();
	}

	initArray(tiles = false) {
		let arr = new Array(this.dy);
		for (let i = 0; i < arr.length; i++) {
			arr[i] = new Array(this.dx)
			for (let j = 0; j < arr[i].length; j++) {
				if (tiles) {
					arr[i][j] = new Tile(j, i, this.sz, random() < 0.2);
				} else {
					arr[i][j] = 0;				
				}
			}
		}
		return arr;
	}

	update() {
		// https://en.wikipedia.org/wiki/Conway%27s_Game_of_Life    

		// caclulate the living neighbours
		this.nbs = this.initArray();
		for (let y = 0; y < this.dy; y++) {
			for (let x = 0; x < this.dx; x++) {
				for (let j = -1; j <= 1; j++) {
					for (let i = -1; i <= 1; i++) {
						if (!(i === 0 && j === 0)) {
							const cy = (y + j + this.dy) % this.dy;
							const cx = (x + i + this.dx) % this.dx;
							if (this.tiles[cy][cx].status) this.nbs[y][x]++;
						}
					}
				}
			}
		}

		// 1. Any live cell with two or three live neighbours survives.
    // 2. Any dead cell with three live neighbours becomes a live cell.
    // 3. All other live cells die in the next generation. Similarly, all other dead cells stay dead.
		for (let y  = 0; y < this.dy; y++) {
			for (let x = 0; x< this.dx; x++) {
				if (this.tiles[y][x].status && this.nbs[y][x] >= 2 && this.nbs[y][x] <= 3) {
					// rule 1.: no action needed, it is alive
					this.tiles[y][x].status = true;
				} else if (!this.tiles[y][x].status && this.nbs[y][x] === 3) {
					// rule 2: alive dead cells with 3 neighbours
					this.tiles[y][x].status = true;
				} else {
					// rule 3: die
					this.tiles[y][x].status = false;
				}
			}
		}

		// end update()
	}

	show(clrs) {
		for (let y = 0; y < this.dy; y++) {
			for (let x = 0; x< this.dx; x++) {
				this.tiles[y][x].show(clrs)
			}
		}		
	}
}

class Tile {
	constructor(x, y, sze, status) {
		this.x = x;
		this.y = y;
		this.sze = sze;
		this.status = status;
		this.pos = createVector(
			x * Tile.getWidth(sze) + ((y % 2 === 0) ? 0 : 0.5 * Tile.getWidth(sze)),
			y * Tile.getHeight(sze) * 3 / 4 // 0.5 * sze
		);
		// this.pos.x = (x * 0.5) * Tile.getWidth(sze)
		// this.pos.y = (y * 0.5) * Tile.getHeight(sze)
	}

	static getWidth(sze) {
		return sqrt(3) * sze * 0.5;
	}
	static getHeight(sze) {
		return sze;
	}
	static getSpacingX(sze) {
		return Tile.getWidth(sze);
	}
	static getSpacingY(sze) {
		return Tile.getHeight(sze) * 3 / 4;
	}

	show(clrs) {
		// if (!this.status) return;

		push();

		stroke(clrs[0])
		fill(clrs[1])
		stroke("white")
		fill(0)
		// circle(this.pos.x, this.pos.y, this.sze)
		const ww = Tile.getWidth(this.sze) ;
		const hh = Tile.getHeight(this.sze) ;
		// noStroke()

		// translate(this.pos.x, this.pos.y)
		const ctx = drawingContext;
		const gradient = ctx.createLinearGradient(-ww + this.pos.x, -hh + this.pos.y, ww + this.pos.x, hh + this.pos.y);
		gradient.addColorStop(0, clrs[0]);
		gradient.addColorStop(1, clrs[1]);
		//gradient.addColorStop(0, "yellow");
		//gradient.addColorStop(1, "red");
		ctx.fillStyle = gradient;

		ctx.shadowBlur = this.sze * 1.33;
		ctx.shadowColor = "white";

		if (!this.status) {
			ctx.shadowBlur = 0;
			stroke("grey")
			noFill();
		}

		beginShape()
		vertex(this.pos.x, this.pos.y-hh * 0.5)
		vertex(this.pos.x + ww * 0.5, this.pos.y - hh * 0.25)
		vertex(this.pos.x + ww * 0.5, this.pos.y + hh * 0.25)
		vertex(this.pos.x, this.pos.y + hh * 0.5)
		vertex(this.pos.x-ww * 0.5, this.pos.y + hh * 0.25)
		vertex(this.pos.x-ww * 0.5, this.pos.y - hh * 0.25)
		endShape(CLOSE)

		/*
		noStroke()
		fill(255)
		text("" + ~~this.x + " " + ~~this.y, this.pos.x, this.pos.y);
		*/
		pop();		
	}
}
